<?php
require_once 'db.php';
$states=getStates($conn); $districts=getDistricts($conn); $default=getDefaultDistrict($conn);
$districtId=isset($_GET['district_id'])?(int)$_GET['district_id']:(int)$default['id'];
$district=getDistrict($conn,$districtId)?:$default;
$results=rows($conn,"SELECT r.*,v.name variety_name,v.variety_code,v.tagline,v.drought_tolerance,v.disease_resistance,v.heat_tolerance,v.flood_tolerance,v.yield_potential,v.maturity_days,v.water_requirement,c.name crop_name,c.icon crop_icon,g.motif_kmer,g.drought_allele,g.disease_allele,g.heat_allele,g.yield_qtl,s.soil_suitability,s.water_suitability,s.temperature_suitability,s.rainfall_suitability,s.climate_resilience_score,rr.drought_risk,rr.disease_risk,rr.heat_risk,rr.flood_risk,rr.environmental_risk,rr.sustainability_score,rr.overall_risk FROM recommendation_scores r JOIN varieties v ON v.id=r.variety_id JOIN crops c ON c.id=v.crop_id LEFT JOIN genomic_profiles g ON g.variety_id=v.id LEFT JOIN variety_environment_suitability s ON s.variety_id=v.id LEFT JOIN variety_risk_scores rr ON rr.variety_id=v.id WHERE r.district_id=? ORDER BY r.overall_score DESC",'i',$district['id']);
$top=$results[0]??null;
$soil=one($conn,"SELECT * FROM soil_profiles WHERE district_id=?",'i',$district['id']);
$rotation=rows($conn,"SELECT cr.crop_year,cr.season,c.name crop_name,cr.rotation_effect FROM crop_rotation_history cr JOIN crops c ON c.id=cr.crop_id WHERE cr.district_id=? ORDER BY cr.crop_year DESC",'i',$district['id']);
page_header('Crop Recommendation','recommendation');
?>
